// Regenerates test/fixtures/prototype-vectors.ts from the prototype implementation.
//
//   node packages/core/test/fixtures/generate-prototype-vectors.mjs <path-to-prototype>/web/js/niimbot.js
//
// The prototype is a private, out-of-repo project that was verified on a real NIIMBOT B1.
// Inputs below are synthetic. The expected bytes therefore prove equivalence with the prototype,
// not behavior on hardware.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { tmpdir } from "node:os";

const source = process.argv[2];
if (!source) {
  console.error("usage: node generate-prototype-vectors.mjs <path to prototype web/js/niimbot.js>");
  process.exit(1);
}

// Load the prototype with its UI-string import stubbed out and its private helpers exported.
const text = readFileSync(source, "utf8")
  .replace(/^import \{t\} from "\.\/i18n\.js";$/m, "const t = () => '';")
  .concat("\nexport {packet, imagePackets};\n");
const tmpFile = join(tmpdir(), `niimbot-reference-${process.pid}.mjs`);
writeFileSync(tmpFile, text);
const ref = await import(pathToFileURL(tmpFile).href);

const hex = (bytes) => Buffer.from(bytes).toString("hex");

// Deterministic pseudo-random RGBA image (same generator as test/helpers.ts).
function syntheticImage(width, height, seed) {
  let s = seed >>> 0;
  const next = () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return s >>> 24;
  };
  const data = new Uint8ClampedArray(width * height * 4);
  for (let i = 0; i < width * height; i++) {
    data[i * 4] = next();
    data[i * 4 + 1] = next();
    data[i * 4 + 2] = next();
    data[i * 4 + 3] = next() < 32 ? 0 : 255;
  }
  return { width, height, data };
}

// Same pixel loop as the prototype's canvasToRows, fed from an ImageData-shaped object.
function referenceRows({ width, height, data }) {
  const HEAD_DOTS = 384;
  const canvas = {
    width,
    height,
    getContext: () => ({ getImageData: () => ({ data }) }),
  };
  const px = canvas.getContext("2d").getImageData(0, 0, width, height).data;
  const offset = Math.floor((HEAD_DOTS - width) / 2);
  const rows = [];
  for (let y = 0; y < height; y++) {
    const row = new Uint8Array(HEAD_DOTS / 8);
    for (let x = 0; x < HEAD_DOTS; x++) {
      const sx = x - offset;
      if (sx < 0 || sx >= width) continue;
      const i = (y * width + sx) * 4;
      const gray = (px[i] * 299 + px[i + 1] * 587 + px[i + 2] * 114) / 1000;
      if (gray < 128 && px[i + 3] > 0) row[x >> 3] |= 0x80 >> (x & 7);
    }
    rows.push(row);
  }
  return rows;
}

const row = (fill) => new Uint8Array(48).fill(fill);
const slice = (a, b, c) => {
  const r = new Uint8Array(48);
  r.fill(a, 0, 16);
  r.fill(b, 16, 32);
  r.fill(c, 32, 48);
  return r;
};

const packets = [
  { name: "connect", cmd: 0xc1, data: null },
  { name: "setDensity3", cmd: 0x21, data: [3] },
  { name: "printStart", cmd: 0x01, data: [0, 1, 0, 0, 0, 0, 0] },
  { name: "setPageSize", cmd: 0x13, data: [0x01, 0x2c, 0x01, 0x80, 0x00, 0x01] },
  { name: "getInfoBattery", cmd: 0x40, data: [10] },
  { name: "maxData", cmd: 0x85, data: Array.from({ length: 255 }, (_, i) => i) },
].map(({ name, cmd, data }) => ({
  name,
  cmd,
  data,
  hex: hex(data ? ref.packet(cmd, data) : ref.packet(cmd)),
}));

const rowSets = [
  {
    name: "mixed",
    rows: [row(0), row(0), row(0), row(0xaa), row(0xaa), row(0xff), slice(0xff, 0x00, 0x0f), row(0)],
  },
  { name: "longEmptyRun", rows: Array.from({ length: 300 }, () => row(0)) },
  { name: "longBlackRun", rows: Array.from({ length: 256 }, () => row(0xff)) },
  { name: "singleBlack", rows: [row(0xff)] },
].map(({ name, rows }) => ({
  name,
  rows: rows.map(hex),
  packets: ref.imagePackets(rows).map(hex),
}));

const imageSpecs = [
  { name: "narrow", width: 10, height: 3, seed: 1 },
  { name: "oddNarrow", width: 33, height: 2, seed: 2 },
  { name: "exact", width: 384, height: 1, seed: 3 },
  { name: "wideEven", width: 400, height: 2, seed: 4 },
  { name: "wideOdd", width: 385, height: 2, seed: 5 },
];
const images = imageSpecs.map((spec) => ({
  ...spec,
  rows: referenceRows(syntheticImage(spec.width, spec.height, spec.seed)).map(hex),
}));

const out = `// GENERATED by generate-prototype-vectors.mjs. Do not edit by hand.
// Source: the prototype's web/js/niimbot.js (223 lines when generated on 2026-10-12), run on synthetic inputs.
// Proves equivalence with the prototype, which was verified on a real NIIMBOT B1; it is not hardware evidence itself.

export const packetVectors: readonly { name: string; cmd: number; data: number[] | null; hex: string }[] = ${JSON.stringify(packets, null, 2)};

export const rowVectors: readonly { name: string; rows: string[]; packets: string[] }[] = ${JSON.stringify(rowSets, null, 2)};

export const imageVectors: readonly { name: string; width: number; height: number; seed: number; rows: string[] }[] = ${JSON.stringify(images, null, 2)};
`;
const target = join(dirname(fileURLToPath(import.meta.url)), "prototype-vectors.ts");
writeFileSync(target, out);
console.log(`wrote ${target}`);
